<?php require_once '../config/config.php';require_admin();$type=$_GET['type']??'courses';$allowed=['academies','courses','course_categories','freelancers','freelancer_categories','inquiries'];if(!in_array($type,$allowed,true))redirect('index.php');$labels=['academies'=>'Academies','courses'=>'Courses','course_categories'=>'Course categories','freelancers'=>'Freelancers','freelancer_categories'=>'Skills','inquiries'=>'Inquiries'];$label=$labels[$type];$editId=(int)($_GET['edit']??0);$editing=null;if($editId){$st=db()->prepare("SELECT * FROM `$type` WHERE id=?");$st->execute([$editId]);$editing=$st->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){db()->prepare("DELETE FROM `$type` WHERE id=?")->execute([$id]);flash("$label item deleted.");redirect("manage.php?type=$type");}if($action==='save'&&$type!=='inquiries'){if($type==='academies'){$data=[trim($_POST['name']),trim($_POST['description']),trim($_POST['location']),upload_image('image',$editing['image']??null)];$cols='name,description,location,image';}elseif($type==='courses'){$data=[trim($_POST['name']),(int)$_POST['academy_id'],(int)$_POST['category_id'],trim($_POST['description']),(float)$_POST['fee'],trim($_POST['duration']),trim($_POST['location']),upload_image('image',$editing['image']??null),(int)isset($_POST['featured'])];$cols='name,academy_id,category_id,description,fee,duration,location,image,featured';}elseif($type==='freelancers'){$data=[trim($_POST['name']),(int)$_POST['category_id'],trim($_POST['bio']),trim($_POST['experience']),trim($_POST['location']),upload_image('image',$editing['image']??null),(int)isset($_POST['featured'])];$cols='name,category_id,bio,experience,location,image,featured';}else{$data=[trim($_POST['name'])];$cols='name';}if($id){$parts=implode(',',array_map(fn($c)=>"$c=?",explode(',',$cols)));$data[]=$id;db()->prepare("UPDATE `$type` SET $parts WHERE id=?")->execute($data);}else{$marks=implode(',',array_fill(0,count($data),'?'));db()->prepare("INSERT INTO `$type` ($cols) VALUES ($marks)")->execute($data);}flash("$label saved successfully.");redirect("manage.php?type=$type");}}$rows=db()->query("SELECT * FROM `$type` ORDER BY id DESC")->fetchAll();$academies=db()->query("SELECT id,name FROM academies ORDER BY name")->fetchAll();$courseCats=db()->query("SELECT id,name FROM course_categories ORDER BY name")->fetchAll();$skillCats=db()->query("SELECT id,name FROM freelancer_categories ORDER BY name")->fetchAll();$pageTitle=$label;require '../includes/admin_header.php';$f=flash();if($f):?><div class="notice"><?=$f['message']?></div><?php endif;?><div class="admin-head"><h2><?=$editing?'Edit':'Manage'?> <?=$label?></h2><?php if(!$editing&&$type!=='inquiries'):?><a class="btn btn-primary" href="?type=<?=$type?>&edit=new">Add new +</a><?php endif;?></div><?php if(($editing&&$editId===0)||isset($_GET['edit'])&&$_GET['edit']==='new'):?><div class="form-card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$editing['id']??0?>"><div class="form-grid"><?php if(in_array($type,['academies','courses','freelancers','course_categories','freelancer_categories'])):?><div class="field"><label>Name</label><input class="input" name="name" required value="<?=e($editing['name']??'')?>"></div><?php endif;?><?php if($type==='academies'):?><div class="field"><label>Location</label><input class="input" name="location" value="<?=e($editing['location']??'')?>"></div><div class="field full"><label>Description</label><textarea class="textarea" name="description"><?=e($editing['description']??'')?></textarea></div><?php elseif($type==='courses'):?><div class="field"><label>Academy</label><select class="select" name="academy_id"><?php foreach($academies as $x):?><option value="<?=$x['id']?>" <?=($editing['academy_id']??0)==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Category</label><select class="select" name="category_id"><?php foreach($courseCats as $x):?><option value="<?=$x['id']?>" <?=($editing['category_id']??0)==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Fee (PKR)</label><input class="input" type="number" name="fee" value="<?=e((string)($editing['fee']??0))?>"></div><div class="field"><label>Duration</label><input class="input" name="duration" value="<?=e($editing['duration']??'')?>"></div><div class="field"><label>Location</label><input class="input" name="location" value="<?=e($editing['location']??'')?>"></div><div class="field full"><label>Description</label><textarea class="textarea" name="description"><?=e($editing['description']??'')?></textarea></div><?php elseif($type==='freelancers'):?><div class="field"><label>Skill category</label><select class="select" name="category_id"><?php foreach($skillCats as $x):?><option value="<?=$x['id']?>" <?=($editing['category_id']??0)==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Experience</label><input class="input" name="experience" value="<?=e($editing['experience']??'')?>"></div><div class="field"><label>Location</label><input class="input" name="location" value="<?=e($editing['location']??'')?>"></div><div class="field full"><label>Bio</label><textarea class="textarea" name="bio"><?=e($editing['bio']??'')?></textarea></div><?php endif;?><?php if(in_array($type,['academies','courses','freelancers'])):?><div class="field"><label>Image</label><input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp"><span class="upload-note">JPG, PNG or WEBP · max 3MB</span></div><?php endif;?><?php if(in_array($type,['courses','freelancers'])):?><div class="field" style="align-content:center"><label><input type="checkbox" name="featured" <?=!empty($editing['featured'])?'checked':''?>> Featured listing</label></div><?php endif;?></div><br><button class="btn btn-primary">Save <?=$label?></button> <a class="btn btn-secondary" href="?type=<?=$type?>">Cancel</a></form></div><?php endif;?><div class="table-wrap"><table class="table"><thead><tr><th>Name / subject</th><th>Details</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><b><?=e($row['name']??$row['message']??'Inquiry')?></b></td><td><?=e($row['email']??$row['location']??$row['description']??$row['inquiry_type']??'')?></td><td><?=isset($row['created_at'])?date('M j, Y',strtotime($row['created_at'])):'—'?></td><td><?php if($type!=='inquiries'):?><a class="action" href="?type=<?=$type?>&edit=<?=$row['id']?>">Edit</a><?php endif;?><form style="display:inline" method="post" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="action delete" style="border:0;background:none;padding:0;font:inherit;cursor:pointer">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/admin_footer.php'; ?>